window.RP_SESSION={"id":"S-0100a2a911d3","messages":[{"id":"RP-0197652","time":"2026-07-22T14:44:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 지금…","characters":["P-6a1a99e98a44"]},{"id":"RP-0197653","time":"2026-07-22T14:44:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"생각을 하나 하고있습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0197654","time":"2026-07-22T14:44:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그것도 단순한 생각이 아닙니다.\n\n무려…!","characters":["P-6a1a99e98a44"]},{"id":"RP-0197655","time":"2026-07-22T14:44:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-6a1a99e98a44"]},{"id":"RP-0197656","time":"2026-07-22T14:44:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'가델랏 허그'의 지능 판정 :\n[6] + [1] = [7]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-0197657","time":"2026-07-22T14:45:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"엄청나게 단순한 생각이지요.\n\n여느때처럼 점심밥으로 뭐가 나올지 생각하면서, 농땡이나 피우고 있습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0197658","time":"2026-07-22T14:46:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"하지만 이렇게나 단순하고 멍텅구리인 허그도, 요근래 어쩔 수 없이 느끼게 되버린 한가지가 있습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0197659","time":"2026-07-22T14:47:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"바로, 길드원들의 분위기가 어째선지 무겁고, 우중충한 감이 있기 때문입니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0197660","time":"2026-07-22T14:49:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"아마이 조라던가, 브랜이라던가, 리키라던가. 그렇게 익숙하게 만나왔던 길드원들은 여전히 평범하나, 대 선 배 길드원들의 어깨가 어째 날이 갈수록 굽어지는 것 같습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0197661","time":"2026-07-22T14:51:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"…그러고보니 허그도 아직 해결하지 못한, 언젠간 끝마쳐야할 일들이 두 개 정도 남아있으나,","characters":["P-6a1a99e98a44"]},{"id":"RP-0197662","time":"2026-07-22T14:52:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"지금의 자신은 미숙합니다. 아직 모르는 것도 많고, 다른 이들을 이해하는 것도 어렵기만 할 뿐입니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0197663","time":"2026-07-22T14:53:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그러고 보니, 캠프에서의 마지막 날, 오랜 친우가 자신에게 해주었던 말이 문득 떠오릅니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0197664","time":"2026-07-22T14:56:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"‘가델, 아직도 그때의 일을 마음에 담아두고 있는거야? 너도 이제 그만 좀 놔주라고, 아니면 제대로 끝을 보던가. 너도 불편하고, 걔도 불편할테고, 누구 하나 좋을게 없잖아.\n\n나중에 가서도 정 모르겠으면 얘기해. 난 언제든 여기서 떼굴떼굴 굴러다니고 있으니깐 말이지.\n같이 몸이나 쓰면서 천천히 생각해보자고.’","characters":["P-6a1a99e98a44"]},{"id":"RP-0197665","time":"2026-07-22T14:57:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“음……”","characters":["P-6a1a99e98a44"]},{"id":"RP-0197666","time":"2026-07-22T14:57:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“역시 난 모르겠네.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0197667","time":"2026-07-22T14:58:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 짐을 하나 둘, 보따리에 욱여넣으며 잠깐의 여행을 준비합니다.\n물론 당장은 아니고, 조금 있다가 갈겁니다.\n지금은 새로운 식구들과 함께 시간을 보내야 할 때이니 말입니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0197668","time":"2026-07-22T14:59:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“보로스, 이 기특한 자식.\n여이, 가는 길에 사슴이나 하나 잡아다 줘야겠는걸.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0197669","time":"2026-07-22T14:59:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6a1a99e98a44"]},{"id":"RP-0197670","time":"2026-07-22T14:59:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
